def main():
 seen=set()
 for p in ODIR.glob('batch_*_annotations.csv'):
  if p!=O:seen.update(pd.read_csv(p,usecols=['id']).id.astype(str))
 x=pd.read_csv(B);x=x[~x.id.astype(str).isin(seen)].head(50).copy()
 if len(x)!=50 or set(x.id)!=set(D):raise ValueError('Decisions do not match next blind records.')
 x[['label','confidence','notes']]=[D[i] for i in x.id];o=x[['id','text','label','confidence','notes']].reset_index(drop=True)
